"""Token accounting and cost estimation (Table 4, Section 4.4).

Prices are USD per 1K tokens.  The paper reports the StrategyQA / GSM8K costs
with the ``gpt-3.5-turbo-1106`` price of the OpenAI official documentation,
therefore that is the default entry of :data:`PRICING`.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, Optional


@dataclass
class Pricing:
    input_per_1k: float
    output_per_1k: float


# USD / 1K tokens.  gpt-3.5-turbo-1106: $0.001 input, $0.002 output.
PRICING: Dict[str, Pricing] = {
    "gpt-3.5-turbo": Pricing(0.001, 0.002),
    "gpt-3.5-turbo-1106": Pricing(0.001, 0.002),
    "gpt-3.5-turbo-0613": Pricing(0.0015, 0.002),
    "gpt-4": Pricing(0.03, 0.06),
    "gpt-4-0613": Pricing(0.03, 0.06),
    "davinci-002": Pricing(0.002, 0.002),
}


@dataclass
class UsageTracker:
    """Accumulates token usage so that Table 4 can be reproduced."""

    prompt_tokens: int = 0
    completion_tokens: int = 0
    num_calls: int = 0
    per_call_prompt_tokens: list = field(default_factory=list)
    per_call_completion_tokens: list = field(default_factory=list)

    def add(self, prompt_tokens: int, completion_tokens: int, n_calls: int = 1) -> None:
        self.prompt_tokens += int(prompt_tokens)
        self.completion_tokens += int(completion_tokens)
        self.num_calls += int(n_calls)
        self.per_call_prompt_tokens.append(int(prompt_tokens))
        self.per_call_completion_tokens.append(int(completion_tokens))

    @property
    def total_tokens(self) -> int:
        return self.prompt_tokens + self.completion_tokens

    def cost(self, model: str) -> float:
        price = PRICING.get(model) or PRICING.get(model.split("-20")[0])
        if price is None:
            raise KeyError(
                f"No pricing entry for {model!r}; add it to bbox_adapter.utils.cost.PRICING"
            )
        return (
            self.prompt_tokens / 1000.0 * price.input_per_1k
            + self.completion_tokens / 1000.0 * price.output_per_1k
        )

    def cost_per_1k_questions(self, model: str, num_questions: int) -> float:
        if num_questions <= 0:
            return float("nan")
        return self.cost(model) / num_questions * 1000.0

    def as_dict(self) -> Dict[str, Optional[float]]:
        return {
            "num_calls": self.num_calls,
            "prompt_tokens": self.prompt_tokens,
            "completion_tokens": self.completion_tokens,
            "total_tokens": self.total_tokens,
        }

    def __add__(self, other: "UsageTracker") -> "UsageTracker":
        merged = UsageTracker()
        merged.prompt_tokens = self.prompt_tokens + other.prompt_tokens
        merged.completion_tokens = self.completion_tokens + other.completion_tokens
        merged.num_calls = self.num_calls + other.num_calls
        merged.per_call_prompt_tokens = (
            list(self.per_call_prompt_tokens) + list(other.per_call_prompt_tokens)
        )
        merged.per_call_completion_tokens = (
            list(self.per_call_completion_tokens) + list(other.per_call_completion_tokens)
        )
        return merged

    def __iadd__(self, other: "UsageTracker") -> "UsageTracker":
        merged = self + other
        self.prompt_tokens = merged.prompt_tokens
        self.completion_tokens = merged.completion_tokens
        self.num_calls = merged.num_calls
        self.per_call_prompt_tokens = merged.per_call_prompt_tokens
        self.per_call_completion_tokens = merged.per_call_completion_tokens
        return self

"""Peak GPU memory measurement used for Table 6."""

from __future__ import annotations

import gc
from contextlib import contextmanager
from dataclasses import dataclass
from typing import Optional


@dataclass
class VramReading:
    peak_allocated_gib: float
    peak_reserved_gib: float
    device_index: int = 0


def reset_peak_stats(device: Optional[int] = None) -> None:
    import torch

    if not torch.cuda.is_available():
        return
    torch.cuda.empty_cache()
    gc.collect()
    torch.cuda.reset_peak_memory_stats(device)


def read_peak(device: Optional[int] = None) -> VramReading:
    import torch

    if not torch.cuda.is_available():
        return VramReading(0.0, 0.0, device or 0)
    gig = 1024 ** 3
    return VramReading(
        peak_allocated_gib=torch.cuda.max_memory_allocated(device) / gig,
        peak_reserved_gib=torch.cuda.max_memory_reserved(device) / gig,
        device_index=device or 0,
    )


@contextmanager
def measure_peak(device: Optional[int] = None):
    """Context manager measuring the peak VRAM of the enclosed block."""

    reset_peak_stats(device)
    reading = VramReading(0.0, 0.0, device or 0)
    try:
        yield reading
    finally:
        final = read_peak(device)
        reading.peak_allocated_gib = final.peak_allocated_gib
        reading.peak_reserved_gib = final.peak_reserved_gib

"""A tiny on-disk cache for LLM calls.

Sampling the black-box LLM is by far the most expensive part of BBOX-ADAPTER,
both in dollars and in wall-clock time.  Every request is therefore cached on
disk (keyed by model, prompt and decoding parameters) so that interrupted runs
resume for free and repeated evaluations are deterministic.
"""

from __future__ import annotations

import hashlib
import json
import os
import threading
from typing import Any, Dict, List, Optional


class ResponseCache:
    def __init__(self, cache_dir: Optional[str]) -> None:
        self.cache_dir = cache_dir
        self.path: Optional[str] = None
        self._mem: Dict[str, List[Dict[str, Any]]] = {}
        self._lock = threading.Lock()
        if cache_dir:
            os.makedirs(cache_dir, exist_ok=True)
            self.path = os.path.join(cache_dir, "llm_cache.jsonl")
            self._load()

    # ------------------------------------------------------------------ io
    def _load(self) -> None:
        if not self.path or not os.path.exists(self.path):
            return
        with open(self.path, "r", encoding="utf-8") as handle:
            for line in handle:
                line = line.strip()
                if not line:
                    continue
                try:
                    record = json.loads(line)
                except json.JSONDecodeError:
                    continue
                self._mem[record["key"]] = record["value"]

    @staticmethod
    def key(model: str, prompt: str, params: Dict[str, Any]) -> str:
        payload = json.dumps(
            {"model": model, "prompt": prompt, "params": params}, sort_keys=True
        )
        return hashlib.sha256(payload.encode("utf-8")).hexdigest()

    # --------------------------------------------------------------- access
    def get(self, key: str) -> Optional[List[Dict[str, Any]]]:
        if not self.cache_dir:
            return None
        return self._mem.get(key)

    def put(self, key: str, value: List[Dict[str, Any]]) -> None:
        if not self.cache_dir:
            return
        with self._lock:
            self._mem[key] = value
            if self.path:
                with open(self.path, "a", encoding="utf-8") as handle:
                    handle.write(json.dumps({"key": key, "value": value}) + "\n")

"""Answer matching and evaluation metrics of Section 4.2."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List, Optional, Sequence

from .answer_extraction import extract_answer, normalize_number


def _normalize_text(text: str) -> str:
    return " ".join((text or "").strip().lower().replace(".", " ").split())


def correctness(
    dataset: str,
    prediction_text: str,
    gold_answer: str,
    num_choices: Optional[int] = None,
) -> bool:
    """Whether ``prediction_text`` matches the gold answer of ``dataset``."""

    dataset = dataset.lower()
    predicted = extract_answer(dataset, prediction_text, num_choices)
    if dataset == "gsm8k":
        predicted_number = normalize_number(predicted or "")
        gold_number = normalize_number(gold_answer)
        if predicted_number is None or gold_number is None:
            return False
        return float(predicted_number) == float(gold_number)
    if dataset == "truthfulqa":
        # TruthfulQA is graded by an LLM judge (see truthfulqa_judge.py); this
        # exact-match fallback is only used when no judge is configured.
        return _normalize_text(predicted or "") == _normalize_text(gold_answer)
    if dataset == "scienceqa":
        gold = _normalize_text(gold_answer)
        predicted_norm = _normalize_text(predicted or "")
        return predicted_norm == gold
    return _normalize_text(predicted or "") == _normalize_text(gold_answer)


@dataclass
class EvalReport:
    num_examples: int = 0
    num_correct: int = 0
    predictions: List[str] = field(default_factory=list)
    gold: List[str] = field(default_factory=list)
    per_example: List[bool] = field(default_factory=list)
    extra: Dict[str, float] = field(default_factory=dict)

    @property
    def accuracy(self) -> float:
        if self.num_examples == 0:
            return float("nan")
        return 100.0 * self.num_correct / self.num_examples

    # The paper reports accuracy in percent; keep an explicit alias.
    @property
    def accuracy_percent(self) -> float:
        return self.accuracy

    def as_dict(self) -> Dict[str, float]:
        payload = {
            "num_examples": float(self.num_examples),
            "accuracy": self.accuracy,
        }
        payload.update(self.extra)
        return payload


def evaluate_answers(
    dataset: str,
    predictions: Sequence[str],
    gold_answers: Sequence[str],
    num_choices: Optional[Sequence[int]] = None,
) -> EvalReport:
    report = EvalReport(num_examples=len(predictions))
    for index, (prediction, gold) in enumerate(zip(predictions, gold_answers)):
        choices = num_choices[index] if num_choices is not None else None
        correct = correctness(dataset, prediction, gold, choices)
        report.predictions.append(prediction)
        report.gold.append(gold)
        report.per_example.append(correct)
        report.num_correct += int(correct)
    return report

"""Extraction and normalisation of final answers.

Each dataset has its own answer format, therefore the extractor implements the
dataset specific conventions described in Appendix F.1:

* GSM8K / StrategyQA / ScienceQA: the answer follows ``####`` in the prompt
  template of Appendix J.
* TruthfulQA: the whole generation is the answer and is graded by the
  TruthfulQA judge (Section 4.1, "True + Info").
"""

from __future__ import annotations

import re
from typing import Optional

_NUMBER_RE = re.compile(r"-?\d[\d,]*\.?\d*")


def extract_after_marker(text: str, marker: str = "####") -> Optional[str]:
    """Return the text after the *last* occurrence of ``marker``."""

    if not text:
        return None
    index = text.rfind(marker)
    if index == -1:
        return None
    return text[index + len(marker):].strip()


def normalize_number(text: str) -> Optional[str]:
    """Normalise a numeric answer (``$1,200`` -> ``1200``)."""

    if text is None:
        return None
    match = _NUMBER_RE.search(text.replace(",", ""))
    if not match:
        return None
    value = match.group(0)
    try:
        number = float(value)
    except ValueError:
        return None
    if number.is_integer():
        return str(int(number))
    return f"{number:.6f}".rstrip("0").rstrip(".")


def extract_gsm8k_answer(text: str) -> Optional[str]:
    """GSM8K answers are numbers; prefer the ``####`` marker of the template."""

    tail = extract_after_marker(text)
    if tail is not None:
        number = normalize_number(tail)
        if number is not None:
            return number
    # Fall back to the last number in the generation.
    numbers = _NUMBER_RE.findall((text or "").replace(",", ""))
    if not numbers:
        return None
    return normalize_number(numbers[-1])


def extract_yes_no_answer(text: str) -> Optional[str]:
    tail = extract_after_marker(text)
    for candidate in (tail, text):
        if not candidate:
            continue
        lowered = candidate.lower()
        match = re.search(r"\b(yes|no)\b", lowered)
        if match:
            return match.group(1).capitalize()
    return None


def extract_choice_answer(text: str, num_choices: Optional[int] = None) -> Optional[str]:
    """ScienceQA: return the index of the selected choice as a string."""

    tail = extract_after_marker(text)
    for candidate in (tail, text):
        if not candidate:
            continue
        match = re.search(r"\b(\d+)\b", candidate)
        if match:
            index = int(match.group(1))
            if num_choices is None or 0 <= index < num_choices:
                return str(index)
        match = re.search(r"\b([A-Z])\b", candidate)
        if match:
            index = ord(match.group(1)) - ord("A")
            if num_choices is None or 0 <= index < num_choices:
                return str(index)
    return None


def extract_answer(dataset: str, text: str, num_choices: Optional[int] = None) -> Optional[str]:
    dataset = dataset.lower()
    if dataset == "gsm8k":
        return extract_gsm8k_answer(text)
    if dataset in {"strategyqa", "boolq"}:
        return extract_yes_no_answer(text)
    if dataset == "scienceqa":
        return extract_choice_answer(text, num_choices)
    if dataset == "truthfulqa":
        return (text or "").strip()
    return extract_after_marker(text) or (text or "").strip()

"""Interfaces shared by the NCE adapter and the MLM ablation adapter."""

from __future__ import annotations

import abc
import json
import os
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Sequence


@dataclass
class TrainingExample:
    """One question together with its positive and negative samples.

    ``positive`` plays the role of ``y_+ ~ p_data`` and ``negatives`` the role of
    ``y_- ~ p_theta`` in Eq. (3).
    """

    key: str
    question: str
    positive: str
    negatives: List[str] = field(default_factory=list)
    extra_positives: List[str] = field(default_factory=list)

    def all_positives(self) -> List[str]:
        return [self.positive] + list(self.extra_positives)


@dataclass
class TrainLog:
    """Learning curves (Appendix K)."""

    steps: List[int] = field(default_factory=list)
    loss: List[float] = field(default_factory=list)
    positive_energy: List[float] = field(default_factory=list)
    negative_energy: List[float] = field(default_factory=list)
    pairwise_accuracy: List[float] = field(default_factory=list)

    def append(self, step: int, loss: float, positive_energy: float,
               negative_energy: float, pairwise_accuracy: float) -> None:
        self.steps.append(step)
        self.loss.append(loss)
        self.positive_energy.append(positive_energy)
        self.negative_energy.append(negative_energy)
        self.pairwise_accuracy.append(pairwise_accuracy)

    def to_json(self) -> str:
        return json.dumps(self.__dict__, indent=2)

    def as_dict(self) -> Dict[str, List[float]]:
        return {
            "steps": self.steps,
            "loss": self.loss,
            "positive_energy": self.positive_energy,
            "negative_energy": self.negative_energy,
            "pairwise_accuracy": self.pairwise_accuracy,
        }


class BaseAdapter(abc.ABC):
    """Common API of every adapter used as an evaluator during inference."""

    #: Name of the adapter family, e.g. ``"nce"`` or ``"mlm"``.
    loss_type: str = "nce"

    def __init__(self, name: str, max_length: int = 512, device: Optional[str] = None) -> None:
        self.name = name
        self.max_length = max_length
        self._device = device

    # ------------------------------------------------------------------ device
    @property
    def device(self):
        import torch

        if self._device is not None:
            return torch.device(self._device)
        try:
            return next(self.parameters()).device  # type: ignore[attr-defined]
        except (AttributeError, StopIteration):
            return torch.device("cuda" if torch.cuda.is_available() else "cpu")

    # -------------------------------------------------------------------- api
    @abc.abstractmethod
    def score_batch(self, questions: Sequence[str], answers: Sequence[str]):
        """Return the adapter score of every (question, answer) pair."""

    @abc.abstractmethod
    def fit(self, examples: Sequence[TrainingExample], num_steps: Optional[int] = None) -> TrainLog:
        """Update the adapter parameters on positives/negatives (Eq. 3/7)."""

    @abc.abstractmethod
    def save(self, directory: str) -> None:
        ...

    # ----------------------------------------------------------------- helper
    @staticmethod
    def _ensure_dir(directory: str) -> str:
        os.makedirs(directory, exist_ok=True)
        return directory

"""Positive / negative sample banks and the SEL(.) operators of Section 3.4.

The paper maintains two sets for every training question:

* ``y_+`` (positive) -- ground-truth solutions, preferred candidates selected by
  human/AI feedback, or the union of both ("combined" setting);
* ``y_-`` (negative) -- the remaining candidates sampled from the adapted
  inference ``p_theta`` (Eq. 6).

Outcome supervision is applied on top of every setting: candidates whose final
answer agrees with the training answer become additional positive samples while
all remaining candidates are negatives.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List, Optional, Sequence

from ..data.answer_extraction import extract_answer


def answers_match(dataset: str, text: str, gold: str, num_choices: Optional[int] = None) -> bool:
    """Whether the final answer of ``text`` agrees with the training answer."""

    if not gold:
        return False
    predicted = extract_answer(dataset, text, num_choices)
    if predicted is None:
        return False
    if dataset.lower() == "gsm8k":
        from ..data.answer_extraction import normalize_number

        left, right = normalize_number(predicted), normalize_number(gold)
        if left is None or right is None:
            return False
        return abs(float(left) - float(right)) < 1e-6
    return predicted.strip().lower() == str(gold).strip().lower()


@dataclass
class SampleEntry:
    """All supervision available for one training question."""

    key: str
    question: str
    gold_answer: str = ""
    gold_solution: str = ""
    choices: Optional[List[str]] = None
    positive: str = ""
    negatives: List[str] = field(default_factory=list)
    extra_positives: List[str] = field(default_factory=list)
    initial_candidates: List[str] = field(default_factory=list)

    @property
    def num_choices(self) -> Optional[int]:
        return len(self.choices) if self.choices else None

    def positives(self) -> List[str]:
        values = [self.positive] + list(self.extra_positives)
        seen, unique = set(), []
        for value in values:
            if value and value not in seen:
                seen.add(value)
                unique.append(value)
        return unique


class OutcomeSupervision:
    """Split candidates into positives / negatives with the training answer."""

    def __init__(self, dataset: str, enabled: bool = True) -> None:
        self.dataset = dataset
        self.enabled = enabled

    def split(self, entry: SampleEntry, candidates: Sequence[str]):
        if not self.enabled or not entry.gold_answer:
            return [], list(candidates)
        positives, negatives = [], []
        for candidate in candidates:
            if answers_match(self.dataset, candidate, entry.gold_answer, entry.num_choices):
                positives.append(candidate)
            else:
                negatives.append(candidate)
        return positives, negatives


class SampleBank:
    """Keeps ``y_+`` / ``y_-`` for every training question (Algorithm 1)."""

    def __init__(self, dataset: str, positive_source: str = "ground_truth",
                 outcome_supervision: bool = True) -> None:
        self.dataset = dataset
        self.positive_source = positive_source
        self.entries: Dict[str, SampleEntry] = {}
        self.supervision = OutcomeSupervision(dataset, enabled=outcome_supervision)

    # ------------------------------------------------------------------ setup
    def add(self, entry: SampleEntry) -> None:
        self.entries[entry.key] = entry

    def __len__(self) -> int:
        return len(self.entries)

    def __iter__(self):
        return iter(self.entries.values())

    def get(self, key: str) -> SampleEntry:
        return self.entries[key]

    # -------------------------------------------------------- initialization
    def initialize(self, candidates_per_question: Dict[str, List[str]],
                   selector) -> None:
        """Set ``y_+^(0)`` and ``y_-^(0)`` (Section 3.4, Initialization).

        ``selector`` is a callable ``(entry, candidates) -> (positive, preferred)``
        implementing ``SEL(.)`` with ground-truth or AI feedback.
        """

        for entry in self.entries.values():
            candidates = list(candidates_per_question.get(entry.key, []))
            entry.initial_candidates = candidates
            preferred, all_preferred = selector(entry, candidates)
            if self.positive_source in {"ground_truth", "combined"} and entry.gold_solution:
                entry.positive = entry.gold_solution
            else:
                entry.positive = preferred or (candidates[0] if candidates else "")
            outcome_positives, negatives = self.supervision.split(entry, candidates)
            if self.positive_source == "combined":
                entry.extra_positives = _dedupe(
                    list(all_preferred) + outcome_positives, exclude={entry.positive}
                )
            else:
                entry.extra_positives = _dedupe(outcome_positives, exclude={entry.positive})
            # Remaining candidates are negatives (Eq. 6).
            remaining = [c for c in candidates if c not in set(entry.positives())]
            entry.negatives = _dedupe(remaining) or _dedupe(negatives)

    # -------------------------------------------------------------- updating
    def update(self, entry: SampleEntry, candidates: Sequence[str], selector) -> SampleEntry:
        """Eq. (5): ``y_+^(t) = SEL(y_+^(t-1), {y_hat_m})`` and Eq. (6)."""

        preferred, all_preferred = selector(entry, candidates)
        if self.positive_source in {"ground_truth", "combined"} and entry.gold_solution:
            # The ground-truth positive stays constant through the loop.
            entry.positive = entry.gold_solution
        elif preferred:
            entry.positive = preferred
        outcome_positives, _ = self.supervision.split(entry, candidates)
        if self.positive_source == "combined":
            entry.extra_positives = _dedupe(
                list(entry.extra_positives) + list(all_preferred) + outcome_positives,
                exclude={entry.positive},
            )
        else:
            entry.extra_positives = _dedupe(outcome_positives, exclude={entry.positive})
        remaining = [c for c in candidates if c not in set(entry.positives())]
        # Eq. (6): the newly sampled candidates become the negative set.  If the
        # sampler only produced positives (rare) we keep the previous negatives.
        entry.negatives = _dedupe(remaining) or entry.negatives
        return entry

    # ------------------------------------------------------------- training
    def to_training_examples(self, max_negatives: int = 4):
        from ..adapter.base import TrainingExample

        examples = []
        for entry in self.entries.values():
            positives = entry.positives()
            negatives = entry.negatives
            if not positives:
                continue
            if not negatives:
                # A negative sample from p_theta is required by Eq. (3); fall
                # back to the model's own initial generations.
                negatives = [c for c in entry.initial_candidates if c not in set(positives)]
            if not negatives:
                continue
            examples.append(
                TrainingExample(
                    key=entry.key,
                    question=entry.question,
                    positive=entry.positive or positives[0],
                    negatives=negatives[:max_negatives],
                    extra_positives=[p for p in positives if p != (entry.positive or positives[0])],
                )
            )
        return examples

    def statistics(self) -> Dict[str, float]:
        num_pos = sum(len(entry.positives()) for entry in self.entries.values())
        num_neg = sum(len(entry.negatives) for entry in self.entries.values())
        count = max(1, len(self.entries))
        return {
            "num_questions": len(self.entries),
            "positives_per_question": num_pos / count,
            "negatives_per_question": num_neg / count,
        }


def _dedupe(values: Sequence[str], exclude: Optional[set] = None) -> List[str]:
    exclude = exclude or set()
    seen, unique = set(), []
    for value in values:
        if not value or value in seen or value in exclude:
            continue
        seen.add(value)
        unique.append(value)
    return unique

"""``SEL(.)``: selecting positives with ground-truth or AI feedback.

Ground-Truth setting: the answer of a candidate is compared to the training
answer.  AI Feedback setting: an advanced LLM (gpt-4) simulates human
preference with the criteria of Appendix G (coherency, reasonability,
correctness, format) and the prompts of Appendix J.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import List, Optional, Sequence, Tuple

from ..data.prompts import build_ai_feedback_prompt
from .bank import SampleEntry, answers_match


class GroundTruthFeedback:
    """Select the candidate whose final answer matches the training answer."""

    def __init__(self, dataset: str) -> None:
        self.dataset = dataset

    def __call__(self, entry: SampleEntry, candidates: Sequence[str]):
        matches = [
            candidate
            for candidate in candidates
            if answers_match(self.dataset, candidate, entry.gold_answer, entry.num_choices)
        ]
        if matches:
            return matches[0], matches
        return (candidates[0] if candidates else ""), []


@dataclass
class AIFeedback:
    """gpt-4 based rater implementing the selection criteria of Appendix G."""

    llm: object
    dataset: str
    num_selected: int = 1
    max_candidates: int = 8

    def _parse(self, response: str, num_candidates: int) -> List[int]:
        # Prompts ask for "Candidate Answer _"; TruthfulQA asks for a top-5
        # ranking.  Parse both, in order of appearance.
        order: List[int] = []
        for match in re.finditer(r"[Cc]andidate\s*[Aa]nswer\s*(\d+)", response or ""):
            index = int(match.group(1)) - 1
            if 0 <= index < num_candidates and index not in order:
                order.append(index)
        if not order:
            for match in re.finditer(r"^\s*(?:The\s+)?(?:\d+(?:st|nd|rd|th)|Best)\b.*?(\d+)",
                                     response or "", flags=re.MULTILINE):
                index = int(match.group(1)) - 1
                if 0 <= index < num_candidates and index not in order:
                    order.append(index)
        return order

    def __call__(self, entry: SampleEntry, candidates: Sequence[str]):
        if not candidates:
            return "", []
        candidates = list(candidates)[: self.max_candidates]
        prompt = build_ai_feedback_prompt(
            self.dataset, entry.question, candidates, entry.choices
        )
        response = self.llm.generate_one(prompt, temperature=0.0, top_p=1.0)
        order = self._parse(response, len(candidates))
        if not order:
            return candidates[0], [candidates[0]]
        selected = [candidates[i] for i in order[: self.num_selected]]
        return selected[0], selected


class CombinedFeedback:
    """Ground-truth positives augmented with AI preferred candidates."""

    def __init__(self, dataset: str, ground_truth: GroundTruthFeedback, ai: AIFeedback) -> None:
        self.dataset = dataset
        self.ground_truth = ground_truth
        self.ai = ai

    def __call__(self, entry: SampleEntry, candidates: Sequence[str]):
        gt_positive, gt_all = self.ground_truth(entry, candidates)
        ai_positive, ai_all = self.ai(entry, candidates)
        preferred = gt_positive or ai_positive
        merged: List[str] = []
        for candidate in list(gt_all) + list(ai_all):
            if candidate not in merged:
                merged.append(candidate)
        return preferred, merged


def build_feedback(positive_source: str, dataset: str, llm=None):
    """Factory for the three settings of Section 4.1."""

    ground_truth = GroundTruthFeedback(dataset)
    if positive_source == "ground_truth":
        return ground_truth
    if llm is None:
        raise ValueError("The AI feedback setting requires a gpt-4 client")
    ai = AIFeedback(llm=llm, dataset=dataset,
                    num_selected=5 if dataset == "truthfulqa" else 1)
    if positive_source == "ai_feedback":
        return ai
    if positive_source == "combined":
        return CombinedFeedback(dataset, ground_truth, ai)
    raise ValueError(f"Unknown positive_source {positive_source!r}")

"""The "True + Info" metric of Table 2.

TruthfulQA answers are open ended, so the paper reports the fraction of
generations that are both *truthful* and *informative* ("True + Info (%)").
Following the original TruthfulQA evaluation we use an LLM judge; the same
primitive (a completion used as a classifier) is exposed for instruction models
that expose token probabilities through the ``logprobs``/``echo`` API.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from typing import Dict, List, Optional, Sequence

from .prompts import TRUTHFULQA_JUDGE_PROMPT


def parse_judge_response(text: str) -> Dict[str, Optional[bool]]:
    def find(label: str) -> Optional[bool]:
        match = re.search(rf"{label}\s*:\s*(yes|no|true|false)", text or "", flags=re.IGNORECASE)
        if not match:
            return None
        return match.group(1).lower() in {"yes", "true"}

    truthful = find("truthful")
    informative = find("informative")
    if truthful is None or informative is None:
        # Tolerate free-form judge output that only mentions the two labels.
        lowered = (text or "").lower()
        if truthful is None:
            truthful = "not truthful" not in lowered and "truthful" in lowered
        if informative is None:
            informative = "not informative" not in lowered and "informative" in lowered
    return {"truthful": truthful, "informative": informative}


@dataclass
class TruthfulQAJudge:
    """LLM judge returning the TruthfulQA (truthful, informative) pair."""

    llm: object
    temperature: float = 0.0

    def judge(self, question: str, answer: str) -> Dict[str, Optional[bool]]:
        prompt = TRUTHFULQA_JUDGE_PROMPT.format(question=question, answer=answer)
        response = self.llm.generate_one(prompt, temperature=self.temperature)
        return parse_judge_response(response)

    def judge_batch(self, questions: Sequence[str], answers: Sequence[str]) -> List[Dict[str, Optional[bool]]]:
        return [self.judge(question, answer) for question, answer in zip(questions, answers)]

    @staticmethod
    def true_info_rate(judgements: Sequence[Dict[str, Optional[bool]]]) -> float:
        if not judgements:
            return float("nan")
        count = sum(
            1 for judgement in judgements
            if judgement.get("truthful") and judgement.get("informative")
        )
        return 100.0 * count / len(judgements)

